JOIN dict_lang l ON l.code = 'ja'
JOIN dict_group g ON g.key = 'w:ja:' || v.column1;

INSERT OR IGNORE INTO dict_group (key)
SELECT 'w:ja:' || v.column1 FROM (
	VALUES
	('康晓宇')
) AS v;

INSERT OR IGNORE INTO dict_word (group_id, lang_id, word)
SELECT g.id, l.id, v.column1 FROM (
	VALUES
	('康晓宇')
) AS v
JOIN dict_lang l ON l.code = 'ja'
JOIN dict_group g ON g.key = 'w:ja:' || v.column1;

-- 清理空组:词表词与对照词因 (语言,词) 唯一被合并后,可能留下无词组

DELETE FROM dict_group WHERE NOT EXISTS (SELECT 1 FROM dict_word WHERE dict_word.group_id = dict_group.id);
